    UI.text(mx + u * 10, y, "ДЛИТЕЛЬНОСТЬ СМЕНЫ ~12 МИНУТ.", u * 0.9f, C_LIGHT);
    // участки
    float rx = mx + cw + u * 20, ry = mt + u * 28, rw = W - cw - u * 30;
