        float lv0 = DISTRICT_TRAFFIC[d] * hourTraffic(gPlannedNight ? 20 * 60 + 30 : 8 * 60 + 30);
        float pm0 = clampf(roundf((0.5f + 0.62f * lv0) * 20) / 20, 0.75f, 1.8f);
